-- SIA: asignacion historica de periodos. Instantanea local del 29/09/2026.
-- Seleccione la base de datos de SIA en phpMyAdmin e importe este archivo completo.
-- 763 objetivos sin periodo: Julio 443, Agosto 183, Septiembre 137 (todos de 2026).
-- Julio: 01/06/2026 a 27/07/2026 inclusive.
-- Agosto: 28/07/2026 a 31/08/2026 inclusive.
-- Septiembre: 01/09/2026 en adelante, SIN fecha maxima en el criterio.
-- Solo se incluyen los IDs de la copia revisada. No alcanza registros futuros.
-- Los 2 registros que ya tenian Septiembre NO se modifican.
-- No cambia fechas, updated_at, datos personales, indicadores ni estado reportado.
-- No cierra ni reabre periodos. Si alguno de los tres esta cerrado, no actualiza.
-- Conserve un respaldo completo antes de importar. NO borre la tabla de respaldo.
-- Repetir el archivo no reasigna registros ni sobrescribe el respaldo original.

-- Revision: comparaciones binarias entre codigos ASCII de periodo para evitar #1267.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sia_respaldo_periodos_20260929 (
    report_id BIGINT UNSIGNED NOT NULL PRIMARY KEY,
    fecha_atencion DATE NOT NULL,
    registro_creado DATETIME NULL,
    registro_actualizado DATETIME NULL,
    periodo_anterior CHAR(7) NULL,
    periodo_nuevo CHAR(7) NOT NULL,
    respaldado_en DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TEMPORARY TABLE IF NOT EXISTS tmp_sia_periodos_20260929 (
    report_id BIGINT UNSIGNED NOT NULL PRIMARY KEY,
    fecha_atencion DATE NOT NULL,
    registro_creado DATETIME NULL,
    registro_actualizado DATETIME NULL,
    periodo_nuevo CHAR(7) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


START TRANSACTION;

SELECT period, is_closed
FROM reporting_periods
WHERE period IN ('2026-07', '2026-08', '2026-09')
ORDER BY period
FOR UPDATE;

SET @sia_periodos_abiertos = (
    SELECT COUNT(*) = 0 FROM reporting_periods
    WHERE period IN ('2026-07', '2026-08', '2026-09') AND is_closed = 1
);

SELECT p.period, 0, NOW(), NOW()
FROM (
    SELECT '2026-07' AS period UNION ALL SELECT '2026-08' UNION ALL SELECT '2026-09'
) AS p
WHERE @sia_periodos_abiertos = 1
  AND NOT EXISTS (SELECT 1 FROM reporting_periods AS existing WHERE BINARY existing.period = BINARY p.period);

SELECT r.id, r.report_date, r.created_at, r.updated_at, r.reporting_period, t.periodo_nuevo, NOW()
FROM reports AS r
JOIN tmp_sia_periodos_20260929 AS t ON t.report_id = r.id
WHERE @sia_periodos_abiertos = 1
  AND r.reporting_period IS NULL
  AND r.report_date = t.fecha_atencion
  AND (r.created_at <=> t.registro_creado)
  AND (r.updated_at <=> t.registro_actualizado)
  AND NOT EXISTS (SELECT 1 FROM sia_respaldo_periodos_20260929 AS b WHERE b.report_id = r.id);

UPDATE reports AS r
JOIN tmp_sia_periodos_20260929 AS t ON t.report_id = r.id
JOIN sia_respaldo_periodos_20260929 AS b ON b.report_id = r.id
SET r.reporting_period = t.periodo_nuevo
WHERE @sia_periodos_abiertos = 1
  AND r.reporting_period IS NULL
  AND b.periodo_anterior IS NULL
  AND r.report_date = t.fecha_atencion
  AND b.fecha_atencion = t.fecha_atencion
  AND (r.created_at <=> t.registro_creado)
  AND (r.updated_at <=> t.registro_actualizado)
  AND (b.registro_creado <=> t.registro_creado)
  AND (b.registro_actualizado <=> t.registro_actualizado)
  AND BINARY b.periodo_nuevo = BINARY t.periodo_nuevo;

SET @sia_periodos_actualizados = ROW_COUNT();

-- Verificar antes del COMMIT. Consultas separadas: compatibles con MySQL,
-- que no permite reutilizar una tabla temporal dos veces en la misma consulta.
SET @sia_objetivos = (SELECT COUNT(*) FROM tmp_sia_periodos_20260929);
SET @sia_objetivos_correctos = (
    SELECT COUNT(*) FROM tmp_sia_periodos_20260929 AS t JOIN reports AS r
        ON r.id = t.report_id AND r.report_date = t.fecha_atencion
        AND (r.created_at <=> t.registro_creado)
        AND BINARY r.reporting_period = BINARY t.periodo_nuevo
);

COMMIT;

SELECT DATABASE() AS base_de_datos,
    @sia_periodos_abiertos AS periodos_abiertos_debe_ser_1,
    @sia_periodos_actualizados AS actualizados_en_esta_ejecucion,
    @sia_objetivos AS objetivos_debe_ser_763,
    @sia_objetivos_correctos AS objetivos_con_periodo_correcto_debe_ser_763;

SELECT reporting_period AS periodo, COUNT(*) AS registros
FROM reports
GROUP BY reporting_period
ORDER BY reporting_period;

-- Si objetivos_con_periodo_correcto es menor que 763, no fuerce una actualizacion.
-- Puede haber registros cambiados, eliminados o un periodo cerrado. Conserve el resultado.

